frame.store("_room_they_asked_about", { let __signature_2917 = Signature { name: "_room_they_asked_about".into(), positional: vec!["line".into(),"asked".into(),"room".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_2919 = Value::dict(); __attrs_2919.dict_set(Value::from("__doc__"), Value::from("The line with another room in it read as the one they asked about.\n\n    A sentence that holds anywhere in a house can still name where it was first written: the\n    dehumidifier line of the condensation answer says \"in a bedroom that gets it badly\", and\n    handed to a bathroom under \"The same goes for the bathroom:\" it says the opposite of what\n    the lead-in claims. The room they asked about is the room in the sentence when it is the\n    same kind of place, so the sentence is about the room they asked about.\n    "))?; __attrs_2919.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_2920 = Value::dict(); __attrs_2919.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_2916 = Frame::module(frame.globals.clone()); let mut __function_2918 = NativeFunction::qualified_with_origin("_room_they_asked_about".into(), "_room_they_asked_about".into(), "bot.modules.answers".into(), __attrs_2919, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/answers.py", first: 6876, last: 6895, qualname: "_room_they_asked_about" }, closure: __closure_2916.clone(), freevars: vec![] }, move |rt, args| __py_219::_room_they_asked_about(rt, __closure_2916.clone(), &__signature_2917, args)); __function_2918 })?;
