frame.store("_a_place_they_asked", { let __signature_2927 = Signature { name: "_a_place_they_asked".into(), positional: vec!["text".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_2929 = Value::dict(); __attrs_2929.dict_set(Value::from("__doc__"), Value::from("True when the follow-up names a place with a place's own preposition.\n\n    \"and in the bathroom\", \"what about under the sink\". A bare thing (\"what about the cake\",\n    \"and what about a turkey\") is not one: the answer about a table is not the answer about a\n    cake, and saying it again with the cake's name in front would be worse than a hedge.\n    "))?; __attrs_2929.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_2930 = Value::dict(); __attrs_2929.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_2926 = Frame::module(frame.globals.clone()); let mut __function_2928 = NativeFunction::qualified_with_origin("_a_place_they_asked".into(), "_a_place_they_asked".into(), "bot.modules.answers".into(), __attrs_2929, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/answers.py", first: 6914, last: 6922, qualname: "_a_place_they_asked" }, closure: __closure_2926.clone(), freevars: vec![] }, move |rt, args| __py_222::_a_place_they_asked(rt, __closure_2926.clone(), &__signature_2927, args)); __function_2928 })?;
frame.store("_key_terms", { let __signature_2932 = Signature { name: "_key_terms".into(), positional: vec!["item".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_2934 = Value::dict(); __attrs_2934.dict_set(Value::from("__doc__"), Value::from("Every phrase the entry is keyed on, however deeply its key is nested.\n\n    An entry's `key` is a tuple of groups, but some entries are written with the phrases in the\n    tuple itself (`('slugs', 'snails', ('keep', 'stop', ...))`), so iterating it once gives the\n    letters of a phrase rather than the phrase. Walking it to the strings is what both readers\n    below need.\n    "))?; __attrs_2934.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_2935 = Value::dict(); __attrs_2934.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_2931 = Frame::module(frame.globals.clone()); let mut __function_2933 = NativeFunction::qualified_with_origin("_key_terms".into(), "_key_terms".into(), "bot.modules.answers".into(), __attrs_2934, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/answers.py", first: 6925, last: 6944, qualname: "_key_terms" }, closure: __closure_2931.clone(), freevars: vec![] }, move |rt, args| __py_223::_key_terms(rt, __closure_2931.clone(), &__signature_2932, args)); __function_2933 })?;
